                    (this.stats.coherenceLevel * 100).toFixed(1) + '%';
                document.getElementById('nonlocalMemory').textContent = 
                    (Math.min(this.stats.hashesCoherent / 1000, 100)).toFixed(1) + '%';
            }

            updateChart() {
                const now = new Date();
                const timeLabel = now.getMinutes() + ':' + now.getSeconds();

                this.chartData.labels.push(timeLabel);
                this.chartData.hashrate.push(this.stats.currentHashrate);
                this.chartData.coherence.push(this.stats.coherenceLevel);

                if (this.chartData.labels.length > 20) {
                    this.chartData.labels.shift();
                    this.chartData.hashrate.shift();
                    this.chartData.coherence.shift();
                }

                this.chart.update();
