            log(message, type = 'info') {
                const logContainer = document.getElementById('logContainer');
                const entry = document.createElement('div');
                entry.className = `log-entry log-${type}`;
                entry.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
                logContainer.appendChild(entry);
                logContainer.scrollTop = logContainer.scrollHeight;
            }

            showSettings() {
                const settings = {
                    poolUrl: prompt('URL del Pool:', 'stratum+tcp://sha256.poolbinance.com:443'),
                    backupPool: prompt('Pool de respaldo:', 'stratum+tcp://btc.poolbinance.com:1800'),
                    intensity: prompt('Intensidad (1-20):', '12')
                };

                if (settings.poolUrl && this.ws) {
                    this.ws.send(JSON.stringify({
                        type: 'update_settings',
                        settings: settings
                    }));
                    this.log('⚙️ Configuración actualizada', 'info');
                }
            }

            generateSessionReport() {
                const sessionTime = this.stats.startTime ? 
                    Math.round((new Date() - this.stats.startTime) / 1000) : 0;

                this.log('📊 RESUMEN DE SESIÓN:', 'info');
                this.log(`⏱️ Tiempo: ${this.formatTime(sessionTime)}`, 'info');
                this.log(`🔍 Hashes: ${this.stats.hashesTotal.toLocaleString()}`, 'info');
                this.log(`🎯 Coherentes: ${this.stats.hashesCoherent.toLocaleString()}`, 'info');
                this.log(`📈 Eficiencia: ${((this.stats.hashesCoherent/this.stats.hashesTotal)*100).toFixed(1)}%`, 'info');
                this.log(`💰 BTC estimados: ${this.stats.estimatedBTC.toFixed(8)}`, 'success');
            }

            formatTime(seconds) {
                const h = Math.floor(seconds / 3600);
                const m = Math.floor((seconds % 3600) / 60);
                const s = seconds % 60;
                return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
            }
        }

        // Inicializar el minero real cuando la página cargue
        document.addEventListener('DOMContentLoaded', () => {
            window.realPMCMiner = new RealPMCMiner();
        });
    </script>
