### **2. Backend Node.js** (`server.js`)

```javascript
const WebSocket = require('ws');
const net = require('net');
const crypto = require('crypto');

class PMCBackendServer {
    constructor() {
        this.wss = new WebSocket.Server({ port: 3000 });
        this.miners = new Map();
        this.poolConnections = new Map();

        this.setupWebSocketServer();
        console.log('🚀 Servidor PMC Backend iniciado en puerto 3000');
    }

    setupWebSocketServer() {
        this.wss.on('connection', (ws) => {
            console.log('🔗 Nuevo cliente conectado');
            const minerId = this.generateMinerId();
            this.miners.set(minerId, { ws, mining: false, stats: {} });

            ws.on('message', (message) => {
                try {
                    const data = JSON.parse(message);
                    this.handleClientMessage(minerId, data);
                } catch (error) {
                    console.error('Error parsing message:', error);
                }
            });

            ws.on('close', () => {
                console.log('❌ Cliente desconectado:', minerId);
                this.miners.delete(minerId);
            });

            // Enviar configuración inicial
            ws.send(JSON.stringify({
                type: 'config',
                config: {
                    pools: [
                        'stratum+tcp://sha256.poolbinance.com:443',
                        'stratum+tcp://btc.poolbinance.com:1800',
                        'stratum+tcp://bs.poolbinance.com:3333'
                    ],
                    version: 'PMC-1.0'
                }
            }));
        });
    }

    handleClientMessage(minerId, data) {
        const miner = this.miners.get(minerId);
        if (!miner) return;

        switch (data.type) {
            case 'start_mining':
                this.startMining(minerId, data.config);
                break;
            case 'stop_mining':
                this.stopMining(minerId);
                break;
            case 'update_settings':
                this.updateSettings(minerId, data.settings);
                break;
        }
    }

    async startMining(minerId, config) {
        const miner = this.miners.get(minerId);
        if (!miner) return;

        miner.mining = true;
        miner.config = config;
        miner.stats = {
            startTime: Date.now(),
            hashesTotal: 0,
            hashesCoherent: 0,
            sharesFound: 0,
            currentHashrate: 0,
            coherenceLevel: 0
        };

        console.log(`🚀 Iniciando minería para: ${config.bitcoinAddress}`);

        // Conectar al pool Stratum
        this.connectToStratumPool(minerId, config);

        // Iniciar simulación de minería PMC
        this.startPMCSimulation(minerId);

        miner.ws.send(JSON.stringify({
            type: 'mining_started',
            message: 'Minería PMC iniciada correctamente'
        }));
    }

    connectToStratumPool(minerId, config) {
        const poolUrl = new URL(config.poolUrl.replace('stratum+tcp://', 'tcp://'));

        const client = net.createConnection({
            host: poolUrl.hostname,
            port: poolUrl.port || 3333
        }, () => {
            console.log(`🔗 Conectado al pool: ${config.poolUrl}`);

            // Enviar subscribe message
            const subscribeMsg = JSON.stringify({
                id: 1,
                method: "mining.subscribe",
                params: []
            }) + '\n';

            client.write(subscribeMsg);
        });

        client.on('data', (data) => {
            this.handleStratumMessage(minerId, data.toString(), client);
        });

        client.on('error', (error) => {
            console.error('Pool connection error:', error);
        });

        client.on('close', () => {
            console.log('Conexión al pool cerrada');
        });

        this.poolConnections.set(minerId, client);
    }

    handleStratumMessage(minerId, data, client) {
        const miner = this.miners.get(minerId);
        if (!miner) return;

        const lines = data.trim().split('\n');

        lines.forEach(line => {
            try {
                const message = JSON.parse(line);
                console.log('📨 Mensaje del pool:', message);

                if (message.method === 'mining.notify') {
                    this.handleMiningNotify(minerId, message.params, client);
                } else if (message.method === 'mining.set_difficulty') {
                    miner.stats.poolDifficulty = message.params[0];
                }

            } catch (error) {
                console.error('Error parsing stratum message:', error);
            }
        });
    }

    handleMiningNotify(minerId, params, client) {
        const miner = this.miners.get(minerId);
        if (!miner || !miner.mining) return;

        const [jobId, prevHash, coinb1, coinb2, merkleBranches, version, nbits, ntime, cleanJobs] = params;

        // Simular procesamiento de trabajo con PMC
        this.processJobWithPMC(minerId, {
            jobId, prevHash, coinb1, coinb2, merkleBranches, version, nbits, ntime
        }, client);
    }

    processJobWithPMC(minerId, job, client) {
        const miner = this.miners.get(minerId);
        if (!miner) return;

        // Simular búsqueda de nonce con filtro PMC
        let nonce = 0;
        const maxNonce = 100000; // Límite para simulación

        const searchInterval = setInterval(() => {
            if (!miner.mining || nonce >= maxNonce) {
                clearInterval(searchInterval);
                return;
            }

            // Aplicar filtro de coherencia PMC
            if (this.spectralCoherenceFilter(nonce, job)) {
                miner.stats.hashesCoherent++;

                // Simular encontrado de share (en realidad, verificar hash)
                if (nonce % 1000 === 0) {
                    this.submitShare(minerId, job, nonce, client);
                }
            }

            miner.stats.hashesTotal++;
            nonce++;

            // Actualizar estadísticas cada segundo
            if (nonce % 100 === 0) {
                this.updateMinerStats(minerId);
            }

        }, 0); // Procesamiento lo más rápido posible
    }

    spectralCoherenceFilter(nonce, job) {
        // Implementación simplificada del filtro espectral TCU
        const data = JSON.stringify(job) + nonce;
        const hash = crypto.createHash('sha256').update(data).digest();

        let coherenceSum = 0;
        for (let i = 0; i < 8; i++) {
            coherenceSum += hash[i] / 255;
        }

        const coherence = coherenceSum / 8;
        return coherence >= 0.682; // Umbral crítico TCU
    }

    submitShare(minerId, job, nonce, client) {
        const miner = this.miners.get(minerId);
        if (!miner) return;

        miner.stats.sharesFound++;

        // Enviar share al pool (simulado)
        const submitMsg = JSON.stringify({
            id: 4,
            method: "mining.submit",
            params: [
                miner.config.workerName,
                job.jobId,
                "00000000", // extranonce2
                job.ntime,
                nonce.toString(16).padStart(8, '0')
            ]
        }) + '\n';

        // client.write(submitMsg); // Descomentar para envío real

        // Notificar al frontend
        miner.ws.send(JSON.stringify({
            type: 'share_found',
            share: {
                jobId: job.jobId,
                nonce: nonce,
                difficulty: miner.stats.poolDifficulty || 1
            }
        }));

        console.log(`✅ Share enviado: ${miner.config.workerName} - Nonce: ${nonce}`);
    }

    updateMinerStats(minerId) {
        const miner = this.miners.get(minerId);
        if (!miner) return;

        const now = Date.now();
        const elapsedSeconds = (now - miner.stats.startTime) / 1000;

        // Calcular hashrate
        miner.stats.currentHashrate = miner.stats.hashesTotal / elapsedSeconds;

        // Calcular BTC estimado
        miner.stats.estimatedBTC = this.calculateEstimatedBTC(miner.stats.currentHashrate, elapsedSeconds);

        // Calcular coherencia
        miner.stats.coherenceLevel = miner.stats.hashesCoherent / Math.max(miner.stats.hashesTotal, 1);
        miner.stats.quantumState = miner.stats.coherenceLevel >= 0.682 ? 'Solitónico' : 'Coherente';

        // Calcular uptime
        miner.stats.uptime = this.formatTime(elapsedSeconds);

        // Enviar estadísticas al frontend
        miner.ws.send(JSON.stringify({
            type: 'mining_stats',
            stats: miner.stats
        }));

        // Enviar información del pool
        miner.ws.send(JSON.stringify({
            type: 'pool_update',
            pool: {
                status: 'Conectado',
                difficulty: miner.stats.poolDifficulty || 1,
                workers: this.miners.size
            }
        }));
    }

    calculateEstimatedBTC(hashrate, elapsedSeconds) {
        // Estimación conservadora basada en dificultad actual
        const btcPerDayPerTh = 0.00000580;
        const currentTh = hashrate / 1e12;
        return currentTh * btcPerDayPerTh * (elapsedSeconds / 86400);
    }

    formatTime(seconds) {
        const h = Math.floor(seconds / 3600);
        const m = Math.floor((seconds % 3600) / 60);
        const s = Math.floor(seconds % 60);
        return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    }

    stopMining(minerId) {
        const miner = this.miners.get(minerId);
        if (miner) {
            miner.mining = false;
            console.log(`⏹️ Minería detenida para: ${minerId}`);
        }

        const poolConn = this.poolConnections.get(minerId);
        if (poolConn) {
            poolConn.end();
            this.poolConnections.delete(minerId);
        }
    }

    updateSettings(minerId, settings) {
        const miner = this.miners.get(minerId);
        if (miner) {
            miner.settings = { ...miner.settings, ...settings };
            console.log(`⚙️ Configuración actualizada para: ${minerId}`);
        }
    }

    generateMinerId() {
        return crypto.randomBytes(8).toString('hex');
    }
}

// Iniciar servidor
new PMCBackendServer();
